(function () {
  const D = DATA.mapsV2;
  D.mapsV1 = JSON.parse(JSON.stringify(D.maps));
  D.contentVersion = 2;
  for (const [id, def] of Object.entries(D.maps)) {
    const art = DATA.hushwood.layouts[id]; if (!art) continue;
    const entry = Object.keys(def.areas).find(a => def.areas[a].entry);
    def.areas.hushwood_art = { name: art.subtitle || art.name, size: "S", art: id, exitStyle: "gate" };
    def.links.push([entry, "hushwood_art"]);
  }
})();
